mapper.select:
SELECT a.*, s.name AS studentName, c.class_name AS className FROM attendance a LEFT JOIN student s ON a.student_id = s.id LEFT JOIN class_info c ON a.class_id = c.id
AND a.class_id = #{query.classId}
AND a.attend_date = #{query.date}
ORDER BY s.name ASC

SELECT s.id AS studentId, s.name AS studentName, s.class_id AS classId, c.class_name AS className, IFNULL(SUM(CASE WHEN a.status = 'present' THEN 1 ELSE 0 END), 0) AS presentDays, IFNULL(SUM(CASE WHEN a.status = 'leave' THEN 1 ELSE 0 END), 0) AS leaveDays, IFNULL(SUM(CASE WHEN a.status = 'absent' THEN 1 ELSE 0 END), 0) AS absentDays, COUNT(a.id) AS totalDays FROM attendance a LEFT JOIN student s ON a.student_id = s.id LEFT JOIN class_info c ON a.class_id = c.id
AND a.class_id = #{classId}
AND a.attend_date >= #{startDate}
AND a.attend_date <= #{endDate}
GROUP BY s.id, s.name, s.class_id, c.class_name ORDER BY s.name ASC

SELECT #{classId} AS classId,
       DATE_FORMAT(#{startDate}, '%Y-%m') AS month,
       IFNULL(SUM(CASE WHEN a.status = 'present' THEN 1 ELSE 0 END), 0) AS presentDays,
       IFNULL(SUM(CASE WHEN a.status = 'leave' THEN 1 ELSE 0 END), 0) AS leaveDays,
       IFNULL(SUM(CASE WHEN a.status = 'absent' THEN 1 ELSE 0 END), 0) AS absentDays,
       COUNT(a.id) AS totalDays
FROM attendance a


        AND a.class_id = #{classId}


        AND a.attend_date >= #{startDate}


        AND a.attend_date <= #{endDate}

SELECT a.attend_date
FROM attendance a
WHERE a.student_id = #{studentId}
  AND a.status IN ('leave', 'absent')
  AND a.attend_date >= #{startDate}
  AND a.attend_date <= #{endDate}
ORDER BY a.attend_date
